        ReviewDecision decision,
        ReviewStatus status,
        String requestId,
        Long supersedesId,
        List<Anomaly> anomalies,
        Instant createdAtUtc) {

    /** 记录类型。 */
    public enum ReviewKind {
        /** 客户端请求的首次审核。 */
        INITIAL,
        /** 追加勘误点后系统生成的复核。 */
        RE_REVIEW
    }

