        /** 通过，点位版本被冻结。 */
        PASSED,
        /** 拒绝，附带具体异常。 */
        REJECTED
    }

    /** 记录状态。 */
    public enum ReviewStatus {
        /** 当前有效。 */
        ACTIVE,
        /** 因追加点位已过期。 */
        EXPIRED
    }
}
