@Transactional
public UploadResult uploadPoints(long sessionId, String requestId, List<NewPoint> points) {
    validateRequestId(requestId);
    if (points == null || points.isEmpty()) throw new BadRequestException("点位列表不能为空");
    for (NewPoint p : points) { nonnull checks }
    DiveSession session = sessionRepository.lockById(sessionId)
        .orElseThrow(() -> new NotFoundException("作业不存在: " + sessionId));
    String hash = hash(sessionId, requestId, points);
    Optional<PointUpload> existing = uploadRepository.findByRequestId(sessionId, requestId);
    if (existing.isPresent()) {
        PointUpload batch = existing.get();
        if (!batch.payloadHash().equals(hash)) throw new ConflictException(...);
        return new UploadResult(sessionId, batch.pointVersion(), batch.pointCount(), batch.firstSeq(), batch.lastSeq(), true);
    }
    int firstSeq = pointRepository.maxSeq(sessionId) + 1;
    Instant now = clock.instant();
    int seq = firstSeq;
    for (NewPoint p : points) pointRepository.insert(sessionId, seq++, p.recordedAtUtc(), p.depthM(), requestId, now);
    int lastSeq = seq - 1;
    int newVersion = session.pointVersion() + 1;
    sessionRepository.updatePointVersion(sessionId, newVersion);
    // expire active review + re-review
    reviewRepository.findActive(sessionId).ifPresent(active -> {
        reviewRepository.markExpired(active.id());
        DiveSession refreshed = new DiveSession(... newVersion ...); // need updated version for evaluator? evaluator doesn't use pointVersion. Just use session.
        List<Anomaly> anomalies = ReviewEvaluator.evaluate(session, pointRepository.findBySessionId(sessionId));
        DiveReview.ReviewDecision decision = anomalies.isEmpty() ? PASSED : REJECTED;
        reviewRepository.insert(sessionId, newVersion, RE_REVIEW, decision, null, active.id(), anomalies, clock.instant());
    });
    uploadRepository.insert(sessionId, requestId, hash, points.size(), firstSeq, lastSeq, newVersion, now);
    return new UploadResult(sessionId, newVersion, points.size(), firstSeq, lastSeq, false);
}
