@Transactional
public ReviewResult requestReview(long sessionId, String requestId) {
    validateRequestId(requestId);
    DiveSession session = lockById or 404;
    int version = session.pointVersion();
    Optional<DiveReview> byIdem = reviewRepository.findByIdemKey(sessionId, requestId);
    if (byIdem.isPresent()) {
        DiveReview existing = byIdem.get();
        if (existing.pointVersion() != version) throw new ConflictException("requestId已用于其他点位版本的审核");
        return toResult(existing, true);
    }
    Optional<DiveReview> passed = reviewRepository.findActivePassedByVersion(sessionId, version);
    if (passed.isPresent()) return toResult(passed.get(), true);
    List<DepthPoint> points = pointRepository.findBySessionId(sessionId);
    List<Anomaly> anomalies = ReviewEvaluator.evaluate(session, points);
    DiveReview.ReviewDecision decision = anomalies.isEmpty() ? PASSED : REJECTED;
